<script>(function(){var lb=document.getElementById('galleryLb'),lbImg=document.getElementById('galleryLbImg'),close=lb.querySelector('.lb-close'),items=document.querySelectorAll('.gallery-grid .g-item img'),open=false;function show(el){lbImg.src=el.src;lb.classList.add('open');lb.setAttribute('aria-hidden','false');document.body.classList.add('lock');open=true}function hide(){lb.classList.remove('open');lb.setAttribute('aria-hidden','true');document.body.classList.remove('lock');open=false}items.forEach(function(img){img.closest('figure').addEventListener('click',function(){show(img)})});close.addEventListener('click',hide);lb.addEventListener('click',function(e){if(e.target===lb||e.target===lbImg)hide()});document.addEventListener('keydown',function(e){if(open&&e.key==='Escape')hide()})})();</script>
